var e={"app.name":`Context Commander`,"app.skipToContent":`Ir al contenido`,"nav.dashboard":`Panel`,"nav.projects":`Proyectos`,"nav.organizations":`Organizaciones`,"nav.registry":`Registro de skills`,"nav.administration":`Administración`,"nav.workspace":`Espacio de trabajo`,"nav.installation":`Instalación`,"nav.preferences":`Preferencias`,"nav.signOut":`Cerrar sesión`,"theme.dark":`Oscuro`,"theme.light":`Claro`,"theme.label":`Tema`,"auth.title":`Iniciar sesión`,"auth.lead":`Pegue un token de acceso personal. Puede crear uno con {command}.`,"auth.token":`Token de acceso`,"auth.submit":`Iniciar sesión`,"auth.failed":`Ese token no se ha aceptado.`,"auth.signedInAs":`Sesión iniciada como {name}`,"auth.sameToken":`El mismo token que usa una CLI o un cliente MCP. No hay una sesión web aparte.`,"auth.indistinct":`Un token revocado y uno que nunca existió se leen aquí igual. Decir cuál de los dos es revelaría, a quien tenga un token robado, que la mitad de su suposición era correcta.`,"common.loading":`Cargando…`,"common.retry":`Reintentar`,"common.cancel":`Cancelar`,"common.close":`Cerrar`,"common.loadMore":`Cargar más`,"common.showingMore":`Se muestran {count} · hay más disponibles`,"common.showingAll":`Se muestran {count} · lista completa`,"common.endOfList":`Fin de la lista`,"common.none":`Ninguno`,"common.never":`Nunca`,"common.unknown":`Desconocido`,"common.you":`Usted`,"error.forbidden.title":`No tiene acceso a esto`,"error.forbidden.body":`Su rol en este proyecto no incluye la capacidad que necesita esta pantalla. Pregunte a una persona propietaria o administradora si debería tenerla.`,"error.notFound.title":`No encontrado`,"error.notFound.body":`Esto no existe o no es visible para usted.`,"error.conflict.title":`Esto cambió mientras lo estaba leyendo`,"error.conflict.body":`Alguien escribió una versión más reciente desde que cargó esta. Lea la versión más reciente, incorpore su cambio y vuelva a intentarlo — sobrescribirla borraría el trabajo de esa persona.`,"error.unavailable.title":`El servidor no responde`,"error.unavailable.body":`No se ha cambiado nada. Inténtelo de nuevo en un momento.`,"error.rateLimited.title":`Demasiadas solicitudes`,"error.rateLimited.body":`Esta credencial está haciendo solicitudes demasiado rápido. Espere un momento y reinténtelo.`,"error.generic.title":`Algo ha salido mal`,"empty.noResults":`Nada coincide con eso`,"empty.noResultsBody":`Pruebe otra búsqueda o quite los filtros.`,"dashboard.title":`Panel`,"dashboard.lead":`Qué ha cambiado, dónde estaba trabajando y si algo le está esperando.`,"dashboard.waiting":`Le está esperando`,"dashboard.yourProjects":`Sus proyectos`,"dashboard.noneWaiting":`Nada le está esperando`,"dashboard.noneWaitingBody":`Ningún traspaso abierto y ninguna denegación que merezca atención.`,"dashboard.noProjects":`Todavía no pertenece a ningún proyecto`,"projects.title":`Proyectos`,"projects.lead":`Todos los proyectos en los que puede actuar. La ruta es como lo dicen las personas; el UUID es lo que entiende el sistema.`,"projects.filter":`Filtrar proyectos…`,"projects.column.project":`Proyecto`,"projects.column.role":`Su rol`,"projects.count":`{count, plural, one {# proyecto} other {# proyectos}}`,"projects.empty":`No es miembro de ningún proyecto`,"projects.emptyBody":`Un proyecto aparece aquí en cuanto alguien le añade a él.`,"project.identity":`Identidad`,"project.path":`Ruta`,"project.uuid":`UUID`,"project.tab.overview":`Resumen`,"project.tab.members":`Miembros`,"project.tab.skills":`Skills`,"project.tab.activity":`Actividad`,"project.notBuilt.title":`Todavía no construido`,"project.notBuilt.artifacts":`Los artefactos, las notas, las políticas y los secretos tienen pantallas diseñadas, pero todavía no hay lectura en la API.`,"handoff.current":`Traspaso actual`,"handoff.summary":`Resumen`,"handoff.completed":`Trabajo realizado`,"handoff.next":`Próximos pasos`,"handoff.references":`Referencias`,"handoff.claim":`Tomarlo`,"handoff.close":`Cerrar el traspaso`,"handoff.create":`Crear un traspaso`,"handoff.status.open":`Abierto`,"handoff.status.claimed":`Tomado`,"handoff.status.closed":`Cerrado`,"handoff.claimedBy":`Tomado por {name}`,"handoff.claimedByYou":`Tomado por usted`,"handoff.none":`No hay ningún traspaso abierto`,"handoff.noneBody":`Aquí no hay nada esperando a que alguien lo retome.`,"handoff.alreadyClaimed":`Otro cliente lo tomó primero`,"handoff.alreadyClaimedBody":`Esa es la respuesta de la coordinación, no un error en su solicitud. Vuelva a leerlo y decida si el trabajo sigue siendo suyo.`,"handoff.history":`Traspasos anteriores`,"handoff.column.created":`Creado`,"handoff.column.status":`Estado`,"members.title":`Miembros`,"members.lead":`Quién puede actuar en este proyecto y con qué rol. Una credencial de cliente no es un miembro — lo es el principal que hay detrás.`,"members.column.principal":`Principal`,"members.column.role":`Rol`,"members.column.added":`Añadido`,"members.add":`Añadir un principal`,"members.count":`{count, plural, one {# miembro} other {# miembros}}`,"skills.title":`Skills`,"skills.lead":`El conjunto efectivo: los vínculos de instalación, organización y proyecto compuestos, y gana el más estrecho para cada skill. Toda sustitución queda a la vista.`,"skills.column.skill":`Skill`,"skills.column.livesAt":`Reside en`,"skills.column.version":`Resuelto`,"skills.column.trust":`Confianza`,"skills.column.state":`Estado`,"skills.browse":`Explorar el registro`,"skills.install":`Instalar un skill`,"skills.empty":`Aquí no se aplica ningún skill`,"skills.emptyBody":`Instale uno desde el registro o publique uno desde este proyecto.`,"registry.title":`Registro de skills`,"registry.lead":`Todo lo que puede ver: los skills de sus proyectos, los de sus organizaciones y los del estante de la instalación. Los agentes buscan en este mismo catálogo.`,"registry.search":`Buscar skills por nombre…`,"registry.column.latest":`Última`,"registry.column.author":`Autoría`,"registry.publish":`Nuevo skill`,"registry.results":`{count, plural, one {# resultado} other {# resultados}} para «{query}»`,"registry.livesAt":`Reside en`,"registry.empty":`El catálogo está vacío`,"registry.emptyBody":`Publique un skill desde un proyecto o promueva uno al estante de la instalación.`,"scope.installation":`Instalación`,"scope.organization":`Organización`,"scope.project":`Proyecto`,"trust.signed":`Firmado`,"trust.unverified":`Sin verificar`,"role.OWNER":`Propiedad`,"role.ADMIN":`Administración`,"role.CONTRIBUTOR":`Colaboración`,"role.READER":`Lectura`,"activity.title":`Actividad`,"activity.lead":`Eventos y auditoría en una sola línea de tiempo. Responden a la misma pregunta — qué ha pasado aquí — y separarlos obliga a quien lee a volver a unirlos.`,"activity.column.time":`Hora`,"activity.column.action":`Acción`,"activity.column.resource":`Recurso`,"activity.column.principal":`Principal`,"activity.column.result":`Resultado`,"activity.result.allow":`Permitido`,"activity.result.deny":`Denegado`,"activity.result.error":`Error`,"activity.empty":`Aquí todavía no ha pasado nada`,"activity.emptyBody":`Las lecturas y escrituras por la API, la CLI y MCP llegan todas a esta línea de tiempo.`,"prefs.title":`Preferencias`,"prefs.lead":`Cómo le habla esta instalación. Estos ajustes acompañan a su cuenta, no a este navegador.`,"prefs.language":`Idioma de la interfaz`,"prefs.languageHelp":`Todo lo que escribe el producto. El contenido escrito por otras personas nunca se traduce.`,"prefs.dateFormat":`Formato de fecha`,"prefs.timeFormat":`Formato de hora`,"prefs.timeZone":`Zona horaria`,"prefs.showUTC":`Mostrar también UTC`,"prefs.numberFormat":`Formato de número`,"prefs.storageUnits":`Unidades de almacenamiento`,"prefs.units.decimal":`GB · decimal, base 1000`,"prefs.units.binary":`GiB · binario, base 1024`,"prefs.notStored":`Las preferencias todavía no se guardan en el servidor, así que por ahora viven en este navegador.`,"prefs.section.language":`Idioma`,"prefs.section.dates":`Fecha y hora`,"prefs.section.numbers":`Números y unidades`,"prefs.dateFormatHelp":`Cómo se escribe una fecha. 03-09-2026 significa dos días distintos según quién lo lea.`,"prefs.timeFormatHelp":`Convención del reloj.`,"prefs.timeZoneHelp":`Las marcas de tiempo se guardan en UTC y se muestran en esta zona.`,"prefs.showUTCHelp":`Para las pantallas de auditoría y seguridad, donde importa tener una referencia común.`,"prefs.storageUnitsHelp":`Cómo se escriben los tamaños en bytes. El valor guardado nunca cambia — solo su lectura.`,"prefs.date.locale":`Seguir el idioma`,"prefs.date.ymd":`AAAA-MM-DD`,"prefs.date.dmy":`DD-MM-AAAA`,"prefs.date.mdy":`MM-DD-AAAA`,"prefs.time.locale":`Seguir el idioma`,"prefs.time.h24":`24 horas`,"prefs.time.h12":`12 horas`,"prefs.tz.device":`Seguir este dispositivo ({zone})`,"prefs.on":`Sí`,"prefs.off":`No`,"prefs.serverFormat":`El servidor nunca envía una cadena con formato. Envía el valor; la interfaz lo lee.`,"members.addHelp":`Por UUID del principal. Ningún punto de la API enumera los principals de una instalación, así que no hay nada entre lo que elegir — copie el UUID de la pantalla de cuenta de esa persona.`,"members.principalPlaceholder":`UUID del principal`,"members.noRemoval":`Quitar a un miembro y cambiar un rol no están construidos: la API no tiene escritura para ninguno de los dos, así que esta pantalla tampoco la ofrece.`,"orgs.title":`Organizaciones`,"orgs.lead":`El ámbito que hay por encima de sus proyectos. En una organización un skill o una gate se imponen una sola vez en lugar de proyecto por proyecto.`,"orgs.column.name":`Organización`,"orgs.column.role":`Su rol`,"orgs.empty":`No pertenece a ninguna organización`,"orgs.emptyBody":`La pertenencia va ligada a la cuenta de una persona, de modo que un principal de servicio nunca tiene ninguna — esa es la respuesta correcta para él, no una denegación.`,"orgs.members":`Miembros`,"orgs.membersLead":`La pertenencia es de cuentas de persona, no de principals: un rol de organización habla de una persona, mientras que un principal de servicio actúa dentro de un proyecto.`,"orgs.audit":`Actividad`,"orgs.column.user":`Cuenta`,"orgs.select":`Seleccione una organización`,"orgs.selectBody":`Elija una a la izquierda para ver sus miembros y su actividad.`,"admin.title":`Administración`,"admin.lead":`La instalación en sí: quién la administra, a quién se le ha denegado algo y las identidades de las que cuelga todo lo demás.`,"admin.tab.overview":`Resumen`,"admin.tab.identities":`Identidades`,"admin.tab.security":`Registro de seguridad`,"admin.admins":`Administración de la instalación`,"admin.adminsLead":`Quien administra la instalación puede leer en todos los proyectos. Conceder o retirar ese permiso no está aquí a propósito — es una operación de la CLI.`,"admin.column.user":`Cuenta`,"admin.column.role":`Rol`,"admin.column.granted":`Concedido`,"admin.createUser":`Crear una cuenta`,"admin.createUserLead":`Una persona que puede tener un token y ser añadida a proyectos.`,"admin.email":`Correo electrónico`,"admin.displayName":`Nombre visible`,"admin.createService":`Crear un principal de servicio`,"admin.createServiceLead":`Una identidad no humana — una tarea de CI, un agente programado. Actúa en los proyectos y aparece en la auditoría como cualquier otra.`,"admin.name":`Nombre`,"admin.description":`Descripción`,"admin.created":`Creado: {name}`,"admin.credentials":`Credenciales`,"admin.credentialsLead":`Los tokens emitidos a un principal. Pegue un UUID de principal para consultarlos.`,"admin.lookup":`Consultar`,"admin.security":`Registro de seguridad`,"admin.identitiesLead":`Aquí se crean las identidades de las que cuelga todo lo demás. Nada en la API enumera cuentas ni principals de servicio, así que esta página los crea y muestra lo que acaba de crear — no tiene ningún directorio que enseñarle.`,"admin.securityLead":`Lo que el servidor rechazó: un token que no se resolvió, una capacidad denegada, una llamada limitada. Separado a propósito de la auditoría de proyecto — una denegación trata a menudo de un proyecto que quien la provoca ni siquiera puede ver, y el patrón que de verdad importa, una credencial tanteando varios proyectos, es invisible desde dentro de cualquiera de ellos.`,"admin.securityNote":`Un inicio de sesión correcto no es un rechazo y no se registra aquí. Lo último que hizo una credencial está en el propio token, como su hora de último uso.`,"admin.column.kind":`Tipo`,"admin.column.reason":`Motivo`,"admin.column.capability":`Capacidad`,"admin.securityEmpty":`No hay nada registrado`,"admin.securityEmptyBody":`Ninguna denegación, ninguna credencial desconocida, nada que mirar. Ese es el caso bueno.`,"tokens.title":`Tokens de acceso`,"tokens.lead":`Las credenciales que usa desde una CLI, un editor o un cliente MCP. Cada una es solo suya — desde aquí no hay forma de emitir un token para otra persona.`,"tokens.column.type":`Cliente`,"tokens.column.created":`Creado`,"tokens.column.lastUsed":`Último uso`,"tokens.column.expires":`Caduca`,"tokens.issue":`Emitir un token`,"tokens.clientType":`Tipo de cliente`,"tokens.expiry":`Validez`,"tokens.expiry.never":`Sin caducidad`,"tokens.expiry.30d":`30 días`,"tokens.expiry.90d":`90 días`,"tokens.expiry.1y":`1 año`,"tokens.revoke":`Revocar`,"tokens.revoked":`Revocado`,"tokens.expired":`Caducado`,"tokens.active":`Activo`,"tokens.empty":`Todavía no hay tokens`,"tokens.emptyBody":`Emita uno para conectar un agente a esta instalación.`,"tokens.justIssued":`Copie este token ahora`,"tokens.justIssuedBody":`Solo se guarda su hash, así que esta es la única vez que puede mostrarse. Cerrar este panel no lo revoca — pero sí significa que ya no podrá volver a leerse.`,"tokens.confirmRevoke":`¿Revocar esta credencial? Todo lo que siga usándola dejará de funcionar de inmediato.`,"artifacts.title":`Artefactos`,"artifacts.lead":`El almacén compartido que los agentes leen y escriben. Cada escritura crea una versión nueva; nada se sobrescribe en su sitio, de modo que una mala escritura se deja atrás leyendo la anterior en lugar de recuperarse de una copia de seguridad.`,"artifacts.column.path":`Ruta`,"artifacts.column.version":`Versión`,"artifacts.column.size":`Tamaño`,"artifacts.column.hash":`Hash del contenido`,"artifacts.empty":`Todavía no hay artefactos`,"artifacts.emptyBody":`El primero aparece cuando un agente escribe por la API, la CLI o MCP.`,"artifacts.history":`Versiones`,"artifacts.content":`Contenido`,"artifacts.select":`Seleccione un artefacto`,"artifacts.selectBody":`Elija una ruta a la izquierda para ver sus versiones y su contenido.`,"artifacts.binary":`Esto no es texto`,"artifacts.binaryBody":`El tipo de contenido dice que esto no es texto, así que no se representa. La versión, el tamaño y el hash de arriba son lo que esta pantalla puede contarle sobre ello.`,"artifacts.viewing":`Mostrando la versión {version}`,"artifacts.latest":`Última`,"artifacts.edit":`Editar`,"artifacts.new":`Nuevo artefacto`,"artifacts.save":`Guardar`,"artifacts.delete":`Eliminar`,"artifacts.confirmDelete":`¿Eliminar {path}? Sus versiones se van con él, y todo lo que lea esa ruta empezará a fallar.`,"artifacts.editingFrom":`Editando a partir de la versión {version}`,"artifacts.editingNew":`Un artefacto nuevo en esta ruta`,"artifacts.newPath":`Ruta`,"artifacts.newPathHelp":`notas/decisiones.md`,"artifacts.contentType":`Tipo de contenido`,"artifacts.staleWrite":`Alguien escribió una versión más reciente mientras usted editaba`,"artifacts.staleWriteBody":`Su guardado se rechazó en lugar de aplicarse — aplicarlo habría borrado el trabajo de esa persona. Cargue la versión más reciente, incorpore su cambio y vuelva a guardar.`,"artifacts.reload":`Cargar la versión más reciente`,"artifacts.concurrency":`Un guardado nombra la versión de la que partió. Si otra persona escribió entretanto, el servidor lo rechaza en vez de sobrescribirla.`,"artifacts.binaryNoEdit":`Esto no es texto, así que no puede editarse aquí. Los agentes lo escriben por la API, la CLI y MCP.`,"secrets.title":`Secretos`,"secrets.lead":`Solo nombres y referencias. Un valor entra una vez y nunca vuelve a salir por esta interfaz — lo que un proyecto obtiene es una referencia que entrega a una gate.`,"secrets.column.name":`Nombre`,"secrets.add":`Añadir un secreto`,"secrets.value":`Valor`,"secrets.delete":`Eliminar`,"secrets.empty":`No hay secretos en este proyecto`,"secrets.emptyBody":`Añada uno aquí, o con la CLI.`,"secrets.neverShown":`El valor se escribe una vez y después nadie puede volver a leerlo, por ningún adaptador. Eliminarlo y volver a añadirlo es la única forma de cambiarlo.`,"secrets.confirmDelete":`¿Eliminar el secreto {name}? Todo lo que use su referencia empezará a fallar.`,"gates.title":`Políticas`,"gates.lead":`Las gates vinculadas a este proyecto y las que hereda. Una gate se ejecuta en un hook y puede rechazar la operación — el rechazo aparece en la línea de tiempo de actividad.`,"gates.column.gate":`Gate`,"gates.column.hook":`Hook`,"gates.column.scope":`Vinculada en`,"gates.column.enabled":`Estado`,"gates.enabled":`Aplicando`,"gates.disabled":`Apagada`,"gates.empty":`Aquí no se aplica ninguna gate`,"gates.emptyBody":`Nada intercepta las operaciones de este proyecto.`,"events.title":`Eventos`,"events.lead":`El flujo de la bandeja de salida. Un evento es lo que consumen otros sistemas; el registro de auditoría que tiene al lado es lo que lee una persona.`,"events.column.seq":`N.º`,"events.column.type":`Tipo`,"events.column.resource":`Recurso`,"events.column.payload":`Carga`,"events.empty":`Todavía no hay eventos`,"skill.versions":`Versiones`,"skill.versionsLead":`Todas las versiones publicadas alguna vez con este nombre. Una versión publicada es inmutable — volver a publicar añade una fila aquí, nunca edita una.`,"skill.content":`Contenido`,"skill.contentLead":`Lo que recibe un agente cuando se resuelve esta versión.`,"skill.provenance":`Procedencia`,"skill.checksum":`Suma de verificación`,"skill.capabilities":`Capacidades declaradas`,"skill.author":`Autoría`,"skill.origin":`Origen`,"skill.promote":`Promover`,"skill.promoteLead":`Llevar el skill a un ámbito más amplio para que lo vean más proyectos. Solo en un sentido: volver a estrecharlo se lo quitaría de debajo a vínculos que eran legítimos cuando se crearon.`,"skill.promoteTo":`Mover a`,"skill.promoted":`Ahora reside en el ámbito {scope}`,"skill.install":`Instalar`,"skill.installed":`Instalado`,"skill.installLead":`Vincular una versión de un skill a este proyecto. El vínculo nombra una versión concreta — no hay resolutor de rangos de versión, así que nada cambia por debajo.`,"skill.notFound":`No existe ese skill`,"skill.notFoundBody":`Puede haberse publicado en un sitio que usted no puede ver.`,"skill.backToRegistry":`Volver al registro`,"skill.pin":`Fijar`,"skill.unpin":`Soltar`,"skill.pinned":`Fijado`,"handoff.createLead":`Lo que la siguiente persona o el siguiente agente necesita para continuar. Aquí lo escribe una persona; los agentes escriben lo mismo por MCP.`,"handoff.summaryHelp":`Una línea. De qué va este trabajo.`,"handoff.completedHelp":`Lo que ya está hecho, para que nadie lo repita.`,"handoff.nextHelp":`Qué hacer a continuación, con detalle suficiente para empezar.`,"handoff.confirmClose":`¿Cerrar este traspaso? Dejará de ser el actual y nadie podrá tomarlo.`,"projects.create":`Nuevo proyecto`,"projects.createLead":`Una ruta y un nombre. La ruta es como se refiere la gente al proyecto y no puede cambiarse después; usted pasa a ser su propietaria o propietario.`,"projects.path":`Ruta`,"projects.pathHelp":`espacio-de-nombres/identificador`,"projects.name":`Nombre visible`,"projects.created":`{path} creado`,"context.title":`Contexto`,"context.lead":`Exactamente lo que recibe un agente cuando empieza aquí — la misma vista ensamblada que devuelve MCP, representada para una persona. Si un agente se comporta de forma extraña, este es el primer sitio donde mirar.`,"context.role":`Actúa como`,"context.capabilities":`Puede`,"context.assembled":`Ensamblado`,"context.budget":`Presupuesto`,"context.budgetUsed":`{used} de {limit}`,"context.budgetLead":`Un paquete tiene un límite de tamaño, y lo que no cabe se nombra en lugar de recortarse. Un agente que no distingue «no hay nada más» de «había más y no te llegó» actuará con confianza sobre media imagen.`,"context.truncated":`Se quedó fuera`,"context.nothingTruncated":`No se quedó nada fuera`,"context.nothingTruncatedBody":`Todo lo que contiene este proyecto cupo en el presupuesto.`,"context.column.what":`Qué`,"context.column.ref":`Cuál`,"context.column.why":`Por qué`,"context.included":`Incluido`,"context.artifacts":`{count, plural, one {# artefacto} other {# artefactos}}`,"context.skills":`{count, plural, one {# skill} other {# skills}}`,"context.recentEvents":`Eventos recientes`,"context.noHandoff":`No hay traspaso en el paquete`,"context.noHandoffBody":`A un agente que empiece aquí se le dice que no hay nada que continuar.`,"context.budgetLimit":`Límite de tamaño`,"context.apply":`Volver a ensamblar`,"skill.pinLead":`Un vínculo fijado es uno por el que este proyecto se decidió y que no quiere que se mueva. Solo puede fijarse un vínculo creado aquí — uno heredado no le pertenece a este proyecto.`,"skill.inherited":`Heredado`,"history.title":`Conversaciones`,"history.lead":`Lo que los clientes registraron de sus propias sesiones, para que un traspaso pueda señalar dónde ocurrió el trabajo de verdad. Esta interfaz no escribe nada de esto — lo aportan los propios clientes.`,"history.column.conversation":`Conversación`,"history.column.started":`Iniciada`,"history.column.by":`Iniciada por`,"history.column.type":`Tipo`,"history.column.recorded":`Registrado`,"history.objects":`Objetos registrados`,"history.lineage":`Linaje`,"history.lineageLead":`Cómo un objeto salió de otro — un resumen a partir de una transcripción, una compactación a partir de un resumen. Es lo que impide confundir un objeto derivado con un original.`,"history.column.from":`Derivado de`,"history.column.to":`Produjo`,"history.column.kind":`Relación`,"history.select":`Seleccione una conversación`,"history.selectBody":`Elija una a la izquierda para ver qué se registró en ella.`,"history.empty":`No hay conversaciones registradas`,"history.emptyBody":`Un cliente las registra mientras trabaja. Todavía nada ha aportado historial a este proyecto.`,"history.noObjects":`En esta conversación no se registró nada`,"history.noLineage":`Sin derivaciones`,"history.noLineageBody":`Todos los objetos de aquí se registraron directamente, ninguno salió de otro.`,"history.notText":`No es texto`,"history.notTextBody":`Un objeto de historial es lo que el cliente registró, y estos bytes no son UTF-8 válido. El hash y el tipo de arriba son lo que esta pantalla puede contarle sobre ello.`,"registry.publishLead":`Un skill es texto de instrucciones que se le entrega a un agente. Publicar crea una versión inmutable — editarla después significa volver a publicar, y ambas versiones se conservan.`,"registry.publishName":`Nombre`,"registry.publishAuthor":`Autoría`,"registry.publishOrigin":`Origen`,"registry.publishScope":`Publicar en`,"registry.publishContent":`Instrucciones`,"registry.published":`Versión {version} publicada`,"registry.publishScopeHelp":`Dónde reside, es decir quién lo ve en el catálogo — no dónde se aplica. Un proyecto puede instalar un skill que resida en cualquier sitio que alcance a ver.`,"gates.bind":`Vincular una gate`,"gates.bindLead":`Solo pueden vincularse gates que el servidor haya registrado de verdad; un vínculo que nombre una gate no registrada hace fallar toda la operación en lugar de ignorarse, así que esta lista es lo que existe.`,"gates.gateName":`Gate`,"gates.hook":`Hook`,"gates.unbind":`Desvincular`,"gates.confirmUnbind":`¿Desvincular {gate} de {hook}? Las operaciones que rechazaba empezarán a pasar.`,"gates.inherited":`Heredada`,"skills.override":`Sustituir`,"skills.overrideLead":`Vincular otra versión en este proyecto, tapando lo que impuso un ámbito más amplio. Un vínculo marcado como no sustituible lo rechaza — para eso está esa marca.`,"skills.overrideVersion":`Versión a vincular`,"orgs.create":`Nueva organización`,"orgs.createLead":`Usted pasa a ser su primera propietaria o propietario. Después podrán asociarse proyectos y skills a ella.`,"orgs.name":`Nombre`,"orgs.addMember":`Añadir miembro`,"orgs.addMemberLead":`Por id de cuenta, no de principal: un rol de organización habla de una persona. Nada en la API enumera cuentas, así que no hay nada entre lo que elegir.`,"orgs.userId":`Id de cuenta`,"settings.title":`Ajustes`,"settings.lead":`Qué es este proyecto y qué puede cambiarse de él desde aquí.`,"settings.identity":`Identidad`,"settings.visibility":`Visibilidad`,"settings.encryption":`Cifrado`,"settings.encryptionBody":`El contenido está cifrado en reposo bajo una clave propia de este proyecto, envuelta a su vez por la clave raíz de la instalación. Los cuerpos de los traspasos y los secretos pasan por ese sobre; los bytes de los artefactos van al almacén de objetos.`,"settings.danger":`Irreversible`,"settings.noWrites":`Nada de esta pantalla puede cambiarse aquí: la API no tiene actualización ni borrado de un proyecto. Renombrar, cambiar la visibilidad y eliminar son operaciones de la CLI, y un control que abriera un diálogo y luego fallara sería peor que su ausencia.`,"settings.connect":`Conectar un agente`,"settings.connectLead":`Apunte un cliente MCP a este servidor con un token de acceso personal. El proyecto se nombra en cada llamada, así que un solo token alcanza todos los proyectos de los que es miembro.`,"settings.mcpEndpoint":`Punto de acceso MCP`,"settings.restEndpoint":`REST`,"dashboard.waitingLead":`Proyectos con un traspaso abierto o tomado — trabajo que alguien dejó para quien venga después.`,"find.open":`Buscar`,"find.placeholder":`Ir a un proyecto, un skill, una pantalla…`,"find.project":`Proyecto`,"find.skill":`Skill`,"find.screen":`Pantalla`,"find.nothing":`Nada coincide con eso`,"find.hint":`Escriba para buscar. ↑↓ se mueve, Intro va, Esc cierra.`,"common.copy":`Copiar`,"common.copied":`Copiado`,"error.crashed.title":`Esta pantalla ha dejado de funcionar`,"error.crashed.body":`Algo de la interfaz ha fallado al dibujar esta página. Nada de lo que estaba viendo se ha cambiado en el servidor. Recargar suele bastar; si no, el detalle de abajo es lo que conviene reportar.`,"error.crashed.reload":`Recargar`,"error.notFoundPage.title":`No existe esa página`,"error.notFoundPage.body":`Esa dirección no corresponde a nada de esta interfaz.`,"error.backToDashboard":`Ir al panel`};export{e as es};